int rc = fdt_create_empty_tree((void *)buf, bufsize);
if (rc == 0) {
    // Mark as a finalized, valid DT in read-only layout (for mutation, caller should open_into a RW buffer)
    FUZZ_SET_ATTR_INT(buf, "is_valid", 1);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 0);
    FUZZ_SET_ATTR_INT(buf, "is_seq", 0);
}
(void)rc;
// Validation: Preconditions ensure a writable buffer with known size; on success we mark the blob valid and non-sequential; further mutations require fdt_open_into().

// Map an error value to a human-readable string
int errval = *FUZZ_PARAM(int);
const char *msg = fdt_strerror(errval);
(void)msg;
// Validation: Arbitrary error codes are allowed; returned pointer is a static string and is not modified.

// Produce a generic void* usable as:
//  - raw writable buffer (not a valid DT)
//  - finalized valid read-only DT (RO layout)
//  - finalized valid writable DT (RW layout via open_into)
// Downstream stubs rely on attributes set here.

// Output object
void *buf = nullptr;

// Choose buffer size in [256, 2048]
unsigned int rsize = *FUZZ_PARAM(unsigned int);
int bufsize = (int)(rsize % 1793u) + 256;

// Allocate a primary buffer to hold content
char *primary = new (std::nothrow) char[bufsize];
if (!primary) { FUZZ_BAIL(); }
buf = (void *)primary; // initialize output immediately

// Helper to extract FDT header fields (big-endian) and attach as attributes
auto set_header_attrs = [&](void *ptr){
    if (!ptr) { FUZZ_BAIL(); }
    struct fdt_header *hdr = (struct fdt_header *)ptr;
    auto be32_to_cpu = [&](const void *p)->uint32_t{
        const unsigned char *b = (const unsigned char *)p;
        return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16) | ((uint32_t)b[2] << 8) | (uint32_t)b[3];
    };
    uint32_t off_dt_struct  = be32_to_cpu(&hdr->off_dt_struct);
    uint32_t off_dt_strings = be32_to_cpu(&hdr->off_dt_strings);
    uint32_t size_dt_struct = be32_to_cpu(&hdr->size_dt_struct);
    uint32_t size_dt_strings= be32_to_cpu(&hdr->size_dt_strings);
    uint32_t totalsize      = be32_to_cpu(&hdr->totalsize);
    uint32_t version        = be32_to_cpu(&hdr->version);
    FUZZ_SET_ATTR_INT(ptr, "off_dt_struct",  (int)off_dt_struct);
    FUZZ_SET_ATTR_INT(ptr, "off_dt_strings", (int)off_dt_strings);
    FUZZ_SET_ATTR_INT(ptr, "size_dt_struct", (int)size_dt_struct);
    FUZZ_SET_ATTR_INT(ptr, "size_dt_strings",(int)size_dt_strings);
    FUZZ_SET_ATTR_INT(ptr, "totalsize",      (int)totalsize);
    FUZZ_SET_ATTR_INT(ptr, "version",        (int)version);
};

// Mode selection: 0=raw buffer, 1=valid RO DT, 2=valid RW DT
int mode = (int)(*FUZZ_PARAM(unsigned int) % 3u);

if (mode == 0) {
    // Raw writable buffer filled with fuzz data; not a valid DT
    std::string seed = FUZZ_PARAM_STR();
    if (!seed.empty()) {
        size_t pos = 0;
        while (pos < (size_t)bufsize) {
            size_t chunk = seed.size();
            if (pos + chunk > (size_t)bufsize) { chunk = (size_t)bufsize - pos; }
            memcpy(primary + pos, seed.data(), chunk);
            pos += chunk;
        }
    }
    FUZZ_SET_ATTR_INT(buf, "bufsize", bufsize);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 1);
    FUZZ_SET_ATTR_INT(buf, "is_valid", 0);
    FUZZ_SET_ATTR_INT(buf, "is_seq", 0);
    // No header attributes for raw buffers.
} else if (mode == 1) {
    // Build a minimal valid DT in-place (RO layout). For mutations, caller must open_into a RW buffer.
    FUZZ_SET_ATTR_INT(buf, "bufsize", bufsize);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 1); // precondition to create
    int rc = fdt_create_empty_tree(buf, bufsize);
    if (rc != 0) { FUZZ_BAIL(); }
    FUZZ_SET_ATTR_INT(buf, "is_valid", 1);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 0);
    FUZZ_SET_ATTR_INT(buf, "is_seq", 0);
    set_header_attrs(buf);
} else {
    // Build a valid DT then convert it into RW layout in-place using open_into (overlapping move allowed by API)
    FUZZ_SET_ATTR_INT(buf, "bufsize", bufsize);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 1);
    int rc1 = fdt_create_empty_tree(buf, bufsize);
    if (rc1 != 0) { FUZZ_BAIL(); }
    // Convert RO layout to RW layout in-place
    int rc2 = fdt_open_into((const void *)buf, buf, bufsize);
    if (rc2 != 0) { FUZZ_BAIL(); }
    FUZZ_SET_ATTR_INT(buf, "is_valid", 1);
    FUZZ_SET_ATTR_INT(buf, "is_writable", 1);
    FUZZ_SET_ATTR_INT(buf, "is_seq", 0);
    set_header_attrs(buf);
}

// Validation: buf is always non-null and attributes consistently describe its state for downstream APIs.

