import random
import string
from typing import List

# This generator produces a valid Devicetree path string (NUL-terminated),
# aiming to exercise both absolute and alias-based paths as used by
# fdt_path_offset() and fdt_path_offset_namelen().
# It crafts realistic node/component names, unit-addresses, and common
# top-level/soc/peripheral layouts to trigger different traversal branches.

HEX = "0123456789abcdef"

# Common top-level nodes and aliases to broaden coverage
TOP_NODES = [
    "",              # root only -> "/"
    "aliases",
    "chosen",
    "cpus",
    "memory@80000000",
    "soc",
    "soc@0",
    "pci",
    "pcie@10000000",
    "amba",
    "firmware",
]

ALIASES = [
    "serial0", "serial1", "uart0", "uart1", "ethernet0", "spi0", "i2c0",
    "mmc0", "mmc1", "usb0", "can0", "gpio0", "led0", "sound", "display",
]

SOC_CHILDREN = [
    "serial@101f1000", "serial@101f2000", "uart@ff000000",
    "i2c@101f4000", "i2c@ff120000",
    "spi@101f5000", "spi@ff130000",
    "ethernet@c0000000", "ethernet@ff0a0000",
    "gpio@101f3000", "gpio@ff220000",
    "sdhci@101f6000", "mmc@ff170000",
    "usb@101f7000", "usb@ff540000",
    "watchdog@101f8000", "timer@101e0000",
]

PCI_CHILDREN = [
    "network@0,0", "storage@1,0", "usb@2,0", "nvme@3,0",
]

AMBA_CHILDREN = [
    "timer@e0004000", "gpio@e000a000", "uart@e0001000",
]

CPUS_CHILDREN = [
    "cpu@0", "cpu@1", "cpu@2", "cpu@3",
]

MEM_CHILDREN = [
    "device-type", "reg", "ranges"  # properties, but harmless as path segments in fuzz
]

GENERIC_NAMES = [
    "bus", "bridge", "cluster", "l2-cache", "intc", "sram@20000000",
    "dma@40000000", "rng@80000000",
]


def rand_hex(n: int, rnd: random.Random) -> str:
    return "".join(rnd.choice(HEX) for _ in range(n))


def rand_unit_address(rnd: random.Random) -> str:
    # Either simple hex or cell-like forms (including comma for PCI style)
    mode = rnd.randint(0, 3)
    if mode == 0:
        return rand_hex(rnd.randint(4, 8), rnd)
    if mode == 1:
        return "0x" + rand_hex(rnd.randint(4, 8), rnd)
    if mode == 2:
        return f"{rnd.randint(0, 15):x}{rnd.randint(0, 15):x}{rnd.randint(0, 15):x}{rnd.randint(0, 15):x},0"
    return rand_hex(8, rnd)


def make_component(base: str, with_unit_prob: float, rnd: random.Random) -> str:
    # Ensure node name starts with a letter or underscore per dtc conventions;
    # allow digits inside. Use hyphen and digits optionally.
    base_clean = base
    if "@" in base:
        # already contains unit address
        return base_clean
    if rnd.random() < with_unit_prob:
        return f"{base_clean}@{rand_unit_address(rnd)}"
    return base_clean


def make_absolute_path(rnd: random.Random) -> str:
    comps: List[str] = []
    # Choose a starting top-level component or just root
    top = rnd.choice(TOP_NODES)
    if top:
        comps.append(make_component(top, 0.3, rnd))
    # Decide a themed subtree to increase validity likelihood
    if comps and comps[0].startswith("soc"):
        pool = SOC_CHILDREN + GENERIC_NAMES
    elif comps and comps[0].startswith("pcie") or (comps and comps[0] == "pci"):
        pool = PCI_CHILDREN
    elif comps and comps[0] == "amba":
        pool = AMBA_CHILDREN
    elif comps and comps[0] == "cpus":
        pool = CPUS_CHILDREN
    else:
        pool = SOC_CHILDREN + GENERIC_NAMES

    depth = rnd.randint(0, 4)
    for _ in range(depth):
        c = rnd.choice(pool)
        comps.append(make_component(c, 0.6, rnd))

    # Occasionally add a property-like leaf (harmless; APIs accept any string)
    if rnd.random() < 0.2:
        comps.append(rnd.choice(["status", "compatible", "reg", "ranges", "#address-cells"]))

    return "/" + "/".join(filter(lambda s: len(s) > 0, comps))


def make_alias_path(rnd: random.Random) -> str:
    alias = rnd.choice(ALIASES)
    # Aliases are first component without leading '/'; the rest is absolute-like tail
    tail = ""
    if rnd.random() < 0.7:
        # Often a direct device under SoC
        tail = "/" + rnd.choice([
            "status", "compatible", "reg", "port@0", "controller", "clocks",
        ]) if rnd.random() < 0.4 else ""
    return f"{alias}{tail}"


def maybe_normalize_trailing(rnd: random.Random, s: str) -> str:
    # Optionally add trailing slash or collapse duplicate separators to exercise parser
    if rnd.random() < 0.15 and s != "/":
        s = s + "/"
    if rnd.random() < 0.15:
        s = s.replace("//", "/")
    return s


def build_path(seed: int) -> str:
    rnd = random.Random(seed)
    mode = rnd.random()
    if mode < 0.65:
        path = make_absolute_path(rnd)
    else:
        path = make_alias_path(rnd)

    # Insert occasional hyphenated names or additional depth to diversify
    if rnd.random() < 0.3 and not path.endswith("/"):
        extra = rnd.choice(["uart", "i2c", "spi", "ethernet", "gpio", "pinctrl"])
        # 50% chance to add unit address
        if rnd.random() < 0.5:
            extra = f"{extra}@{rand_unit_address(rnd)}"
        joiner = "/" if path.startswith("/") else "/"
        path = f"{path}{joiner}{extra}"

    path = maybe_normalize_trailing(rnd, path)

    # Ensure it's not empty and under size limit
    if not path:
        path = "/"
    if len(path) > 4000:
        path = path[:4000]
    return path


def generate(seed: int) -> bytes:
    # Create a valid NUL-terminated path string
    path = build_path(seed)
    # Return as bytes with terminating NUL as typical C-string input
    data = path.encode("utf-8") + b"\x00"
    # Enforce maximum total size
    if len(data) > 4096:
        data = data[:4095] + b"\x00"
    return data
